{
  "countries": [
    {
      "code": "RE",
      "languages": ["フランス語 (ラテン文字)"],
      "plate_note": "フランス本土と同様の欧州型ナンバープレート。白地に黒文字で、左側にEU旗＋フランス国章、右側に2桁の地域番号「974」または「99」＋アルファベット2‑3‑2 の形式（例 AA‑123‑AA）。",
      "scripts": ["latin"],
      "traffic_side": "right"
    },
    {
      "code": "IN",
      "languages": ["ヒンディー語 (デーヴァナーガリー)","英語 (ラテン文字)"],
      "plate_note": "前面は白地に黒文字、背面は黄地に黒文字。形式は「XX 00 AA 0000」(州コード‑年度‑シリーズ‑番号)。例 DL 07 AB 1234。左側にインド国旗と「IND」コードが付く。",
      "scripts": ["devanagari","latin"],
      "traffic_side": "left"
    },
    {
      "code": "LK",
      "languages": ["シンハラ語 (シンハラ文字)","タミル語 (タミル文字)","英語 (ラテン文字)"],
      "plate_note": "白地に黒文字。形式は「AB 1234」(2文字の県コード＋4桁番号)。左側にスリランカ国旗と「SL」コード、右側にシンハラ文字で「ශ්‍රී ලංකා」(シュリー・ラーカ) が入ることも。",
      "scripts": ["sinhala","tamil","latin"],
      "traffic_side": "left"
    },
    {
      "code": "BD",
      "languages": ["ベンガル語 (ベンガル文字)","英語 (ラテン文字)"],
      "plate_note": "白地に黒文字。形式は「DD‑1234」(地区コード2文字＋4桁番号)。左側にバングラデシュ国旗と「BD」コード、ベンガル文字で「বাংলাদেশ」も併記される。",
      "scripts": ["bengali","latin"],
      "traffic_side": "left"
    },
    {
      "code": "NP",
      "languages": ["ネパール語 (デーヴァナーガリー)","英語 (ラテン文字)"],
      "plate_note": "白地に黒文字。形式は「##‑####」(数字2桁＋ハイフン＋数字4桁)で、左側にネパール国旗と「NP」コード、右側にデーヴァナーガリー文字で「नेपाल」表記がある。",
      "scripts": ["devanagari","latin"],
      "traffic_side": "left"
    },
    {
      "code": "BT",
      "languages": ["ゾンカ語 (チベット文字)","英語 (ラテン文字)"],
      "plate_note": "白地に黒文字。形式は「AB‑1234」(2文字アルファベット＋ハイフン＋4桁番号)で、左側にブータン国旗と「BT」コード、右側にゾンカ文字で「འབྲུག」(ブータン) が入る。",
      "scripts": ["tibetan","latin"],
      "traffic_side": "left"
    }
  ]
}
